CREATE OR REPLACE FUNCTION sonde_reject_m0_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION '% is append-only: % rejected', TG_TABLE_NAME, TG_OP USING ERRCODE='restrict_violation'; END; $$ LANGUAGE plpgsql;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION sonde_append_cockpit_event() RETURNS trigger AS $$ BEGIN INSERT INTO m0_cockpit_events(kind, artifact_id, recorded_at) VALUES (TG_ARGV[0], NEW.id::text, NEW.recorded_at); RETURN NEW; END; $$ LANGUAGE plpgsql;
