DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['m0_source_documents','m0_acquisition_attempts','m0_parse_runs','m0_form4_transaction_facts','m0_issuers','m0_listings','m0_broker_assets','m0_sip_daily_bars','m0_market_sessions','m0_job_run_events','m0_cockpit_events'] LOOP EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION sonde_reject_m0_mutation()',t||'_append_only',t); END LOOP; END $$;
